/**
 * HookLifecycleStageMapperEngine — ACP-MS0/P0-U02
 *
 * Reads the authoritative `state/shared/HOOK_REGISTRY.json` (463 hooks as of
 * 2026-05-13, generated by `scripts/build-hook-registry.mjs`) and classifies
 * every hook into a coarse automation-lifecycle stage. The mapping consumes
 * three signals per hook: (1) the settings.json `event` list (PreToolUse /
 * PostToolUse / Stop / UserPromptSubmit / SessionStart / PreCompact), (2) the
 * `// tier: T#` frontmatter (T0 critical blocker → T4 async background, set
 * by H3's classify-hook-tiers.mjs), and (3) hook description keywords.
 *
 * The engine ALSO scans the milestone envelopes under
 * `mcp-server/data/milestones/*.json` for `forge_triple.protective_hook`
 * references and flags hooks that are DECLARED but not yet implemented as
 * `ccmPlanned: true` — these are the "Chain Coverage Map" / "ACP-planned"
 * hooks the milestone owner has reserved but not built. The list is small
 * (one per milestone with a declared protective hook).
 *
 * Pure engine — no I/O at module load. All file reads happen inside method
 * calls, scoped to the invoking call. Singleton exported at the bottom.
 *
 * Acceptance per ACP-MS0/P0-U02 envelope:
 *   - "Inventory hook definitions (existing + CCM planned)" ✓
 *   - "map to automation lifecycle stages" ✓
 *   - "follow 4-LOOP (BUILD → SCRUTINIZE → GAP FILL → TIE UP)" — gated by
 *     per-file scrutiny + 3-of-3 end-of-task gate in the orchestrator.
 *
 * @milestone ACP-MS0 / P0-U02
 */

import * as fs from "node:fs";
import * as path from "node:path";

// ───────────────────────────────────────────────────────────────────────────
// Types

/** Coarse automation-lifecycle stages. Distinct from Claude Code event names
 *  (which describe WHEN the hook fires); these describe WHAT the hook does
 *  in the developer-tools workflow. */
export type AutomationLifecycleStage =
  | "authoring"         // user is composing — context injectors, prompt-time guards
  | "pre_execution"     // before a tool runs — safety/dedup/wiring gates
  | "post_execution"    // after a tool runs — linters, watchers, regen
  | "turn_end_gate"     // Stop hooks that block the turn — test gates, scrutiny
  | "context_boundary"  // PreCompact context handlers
  | "async_background"  // T4 detached / fire-and-forget
  | "unclassified";     // orphan / disabled / no events / unparseable

export interface HookLifecycleEntry {
  /** Stable hook id derived from the .mjs filename (e.g. "scrutinize-before-stop"). */
  id: string;
  /** Repo-relative file path. */
  file: string;
  /** Claude-Code event triggers from settings.json (PreToolUse, Stop, etc.). */
  events: string[];
  /** Tier frontmatter (T0..T4) or null if unclassified. */
  tier: string | null;
  /** Primary stage classification. */
  primaryStage: AutomationLifecycleStage;
  /** Status drawn from the registry: "wired" (in settings.json), "orphan"
   *  (exists on disk but not referenced), "disabled" (explicit disable),
   *  "planned" (referenced from milestone envelope but file does not exist). */
  status: "wired" | "orphan" | "disabled" | "planned";
  /** Description from the hook's own frontmatter / inferred from filename. */
  description: string;
  /** True if this hook is referenced by a milestone envelope's `forge_triple.protective_hook`
   *  field but does not exist on disk yet — the "CCM planned" set per the
   *  ACP-MS0/P0-U02 deliverable spec. */
  ccmPlanned: boolean;
  /** When ccmPlanned is true, the milestone id that declared the hook (e.g. "ACP-MS0"). */
  ccmDeclaredBy?: string;
}

export interface HookLifecycleInventory {
  schemaVersion: 1;
  generated_at: string;
  total_hooks: number;
  by_stage: Record<AutomationLifecycleStage, number>;
  by_status: Record<"wired" | "orphan" | "disabled" | "planned", number>;
  ccm_planned_count: number;
  entries: HookLifecycleEntry[];
}

// Minimal shape of HOOK_REGISTRY.json — only the fields we actually read.
// `events` in the real registry is an array of objects { event, matcher, ... }
// emitted by scripts/build-hook-registry.mjs. The engine ALSO accepts a flat
// string[] for hand-built test fixtures.
interface RegistryEventDetail {
  event?: string;
  matcher?: string;
  timeout?: number | null;
  type?: string;
  layer?: string;
  disabled?: boolean;
  viaBundle?: string;
}
interface RegistryHookEntry {
  id?: string;
  file?: string;
  wired?: boolean;
  disabled?: boolean;
  events?: Array<string | RegistryEventDetail>;
  description?: string;
  tier?: string | null;
}

/**
 * Normalize the registry's events[] field (which contains either strings or
 * `{event, matcher, ...}` objects) into a flat string[] of event names.
 * Empty/malformed entries are dropped. Order is preserved; duplicates are
 * dropped because the same event may fire from multiple settings layers.
 */
function normalizeEvents(raw: RegistryHookEntry["events"]): string[] {
  if (!Array.isArray(raw)) return [];
  const out: string[] = [];
  const seen = new Set<string>();
  for (const e of raw) {
    let name: string | undefined;
    if (typeof e === "string") name = e;
    else if (e && typeof e === "object" && typeof (e as RegistryEventDetail).event === "string") {
      name = (e as RegistryEventDetail).event;
    }
    if (name && !seen.has(name)) {
      seen.add(name);
      out.push(name);
    }
  }
  return out;
}
interface HookRegistry {
  schemaVersion?: number;
  hooks?: RegistryHookEntry[];
}

// Minimal milestone-envelope shape for forge_triple scanning.
interface MilestoneEnvelope {
  id?: string;
  milestone_id?: string;
  forge_triple?: { protective_hook?: string };
}

// ───────────────────────────────────────────────────────────────────────────
// Constants

const REGISTRY_PATH_REL = "state/shared/HOOK_REGISTRY.json";
const HOOKS_DIR_REL = ".claude/hooks";
const MILESTONES_DIR_REL = "mcp-server/data/milestones";

const ALL_STAGES: AutomationLifecycleStage[] = [
  "authoring",
  "pre_execution",
  "post_execution",
  "turn_end_gate",
  "context_boundary",
  "async_background",
  "unclassified",
];

// ───────────────────────────────────────────────────────────────────────────
// Path helpers — env-overridable for tests.

function repoRootCandidates(): string[] {
  const candidates = [
    process.env.PRISM_REPO_ROOT,
    path.resolve(__dirname, "../../.."),
    path.resolve(__dirname, "../../../.."),
    path.resolve(process.cwd(), "."),
    path.resolve(process.cwd(), ".."),
  ].filter(Boolean) as string[];
  return Array.from(new Set(candidates));
}

function resolveRegistryPath(override?: string): string {
  if (override) return override;
  if (process.env.PRISM_HOOK_REGISTRY) return process.env.PRISM_HOOK_REGISTRY;
  for (const root of repoRootCandidates()) {
    const p = path.join(root, REGISTRY_PATH_REL);
    if (fs.existsSync(p)) return p;
  }
  // Return the first candidate even if missing — readInventory will surface
  // a clear `ok:false, error:"registry_not_found"` rather than throw.
  return path.join(repoRootCandidates()[0] ?? process.cwd(), REGISTRY_PATH_REL);
}

function resolveHooksDir(override?: string): string {
  if (override) return override;
  if (process.env.PRISM_HOOKS_DIR) return process.env.PRISM_HOOKS_DIR;
  for (const root of repoRootCandidates()) {
    const p = path.join(root, HOOKS_DIR_REL);
    if (fs.existsSync(p)) return p;
  }
  return path.join(repoRootCandidates()[0] ?? process.cwd(), HOOKS_DIR_REL);
}

function resolveMilestonesDir(override?: string): string {
  if (override) return override;
  if (process.env.PRISM_MILESTONES_DIR) return process.env.PRISM_MILESTONES_DIR;
  for (const root of repoRootCandidates()) {
    const p = path.join(root, MILESTONES_DIR_REL);
    if (fs.existsSync(p)) return p;
  }
  return path.join(repoRootCandidates()[0] ?? process.cwd(), MILESTONES_DIR_REL);
}

// ───────────────────────────────────────────────────────────────────────────
// Stage classification — pure function, exported for direct test access.

/**
 * Map a single registry hook entry to its primary automation-lifecycle stage.
 *
 * @param events  The hook's `events` array from settings.json (e.g. ["PreToolUse"]).
 * @param tier    The hook's tier frontmatter (T0..T4) or null.
 * @param disabled  Whether the hook is explicitly disabled.
 * @returns The primary stage. Deterministic for any given input triple.
 */
export function classifyHookStage(
  events: readonly string[] | undefined,
  tier: string | null | undefined,
  disabled?: boolean,
): AutomationLifecycleStage {
  if (disabled) return "unclassified";

  const ev = new Set(events ?? []);
  const t = tier ?? "";

  // PreCompact dominates regardless of tier — it's the context-boundary handler.
  if (ev.has("PreCompact")) return "context_boundary";

  // T4 (async/background) is its own dispatch lane regardless of event.
  if (t === "T4") return "async_background";

  // Authoring stage — context injectors + prompt-time guards.
  if (ev.has("UserPromptSubmit") || ev.has("SessionStart")) return "authoring";

  // Pre-execution gates — PreToolUse hooks at T0/T1 blocking/advisory tiers.
  if (ev.has("PreToolUse")) return "pre_execution";

  // Post-execution — PostToolUse linters and watchers.
  if (ev.has("PostToolUse")) return "post_execution";

  // Stop hooks — T0 are blocking turn-end gates, others are post-turn observers.
  if (ev.has("Stop")) {
    if (t === "T0") return "turn_end_gate";
    return "post_execution";
  }

  // Anything else with zero recognised events is unclassified (orphan).
  return "unclassified";
}

// ───────────────────────────────────────────────────────────────────────────
// Engine

export class HookLifecycleStageMapperEngine {
  /**
   * Read the hook registry + milestone envelopes and emit a full lifecycle
   * inventory. Pure read — no mutation.
   *
   * @param opts.registryPath    Override the path to HOOK_REGISTRY.json.
   * @param opts.hooksDir        Override the .claude/hooks directory (used
   *                              to detect "planned" hooks — referenced
   *                              from milestone envelopes but absent on disk).
   * @param opts.milestonesDir   Override the milestone envelope directory.
   * @returns A `HookLifecycleInventory` with per-stage and per-status counts.
   * @throws Never — surfaces filesystem errors as a thrown Error only when
   *         the registry itself is unreadable. The engines.md rule says
   *         "throw descriptive errors, never silentCatch" for the registry
   *         path; milestone read errors are gracefully degraded (the
   *         affected milestone is skipped with a console.error trace).
   */
  buildInventory(opts: {
    registryPath?: string;
    hooksDir?: string;
    milestonesDir?: string;
  } = {}): HookLifecycleInventory {
    const registryPath = resolveRegistryPath(opts.registryPath);
    const hooksDir = resolveHooksDir(opts.hooksDir);
    const milestonesDir = resolveMilestonesDir(opts.milestonesDir);

    let raw: string;
    try {
      raw = fs.readFileSync(registryPath, "utf8");
    } catch (e) {
      throw new Error(
        `HookLifecycleStageMapperEngine: registry not readable at ${registryPath}: ${(e as Error).message}`,
      );
    }
    let registry: HookRegistry;
    try {
      registry = JSON.parse(raw) as HookRegistry;
    } catch (e) {
      throw new Error(
        `HookLifecycleStageMapperEngine: registry JSON malformed at ${registryPath}: ${(e as Error).message}`,
      );
    }
    const hooks = Array.isArray(registry.hooks) ? registry.hooks : [];

    const plannedRefs = this._scanMilestonePlannedHooks(milestonesDir, hooksDir);

    // Build the existing-hook entries from the registry.
    const existingIds = new Set<string>();
    const entries: HookLifecycleEntry[] = hooks.map((h) => {
      const id = h.id ?? path.basename(h.file ?? "", ".mjs");
      existingIds.add(id);
      const events = normalizeEvents(h.events);
      const status: HookLifecycleEntry["status"] = h.disabled
        ? "disabled"
        : h.wired
          ? "wired"
          : "orphan";
      const primaryStage = classifyHookStage(events, h.tier ?? null, h.disabled);
      const ccmRef = plannedRefs.byHookId.get(id);
      return {
        id,
        file: h.file ?? `${HOOKS_DIR_REL}/${id}.mjs`,
        events,
        tier: h.tier ?? null,
        primaryStage,
        status,
        description: h.description ?? "",
        // A hook that's both in the registry AND declared by an envelope is
        // tracked as existing — ccmPlanned is reserved for declared-but-absent.
        ccmPlanned: false,
        ccmDeclaredBy: ccmRef?.milestoneId,
      };
    });

    // Append PLANNED entries — hooks declared by milestone forge_triple but
    // not present on disk.
    for (const ref of plannedRefs.plannedOnly) {
      if (existingIds.has(ref.hookId)) continue; // already covered
      entries.push({
        id: ref.hookId,
        file: `${HOOKS_DIR_REL}/${ref.hookId}.mjs`,
        events: [],
        tier: null,
        primaryStage: "unclassified",
        status: "planned",
        description: `CCM-planned (declared by ${ref.milestoneId}.forge_triple.protective_hook)`,
        ccmPlanned: true,
        ccmDeclaredBy: ref.milestoneId,
      });
    }

    // Tally counts.
    const by_stage: Record<AutomationLifecycleStage, number> = {
      authoring: 0,
      pre_execution: 0,
      post_execution: 0,
      turn_end_gate: 0,
      context_boundary: 0,
      async_background: 0,
      unclassified: 0,
    };
    const by_status: Record<"wired" | "orphan" | "disabled" | "planned", number> = {
      wired: 0, orphan: 0, disabled: 0, planned: 0,
    };
    let ccm_planned_count = 0;
    for (const e of entries) {
      by_stage[e.primaryStage] += 1;
      by_status[e.status] += 1;
      if (e.ccmPlanned) ccm_planned_count += 1;
    }

    return {
      schemaVersion: 1,
      generated_at: new Date().toISOString(),
      total_hooks: entries.length,
      by_stage,
      by_status,
      ccm_planned_count,
      entries,
    };
  }

  /**
   * Filter the inventory to a single stage. Useful for stage-by-stage audit.
   *
   * @param inventory  Output of `buildInventory()`.
   * @param stage      The lifecycle stage to filter on.
   * @returns Subset of entries whose primaryStage matches.
   */
  filterByStage(
    inventory: HookLifecycleInventory,
    stage: AutomationLifecycleStage,
  ): HookLifecycleEntry[] {
    return inventory.entries.filter((e) => e.primaryStage === stage);
  }

  /**
   * Filter the inventory to a status (wired / orphan / disabled / planned).
   */
  filterByStatus(
    inventory: HookLifecycleInventory,
    status: HookLifecycleEntry["status"],
  ): HookLifecycleEntry[] {
    return inventory.entries.filter((e) => e.status === status);
  }

  /**
   * Emit a human-readable markdown summary of the inventory.
   *
   * @param inventory  Output of `buildInventory()`.
   * @returns Multiline markdown string suitable for state/shared/.
   */
  renderMarkdown(inventory: HookLifecycleInventory): string {
    const lines: string[] = [];
    lines.push(`# Hook Lifecycle Inventory — ACP-MS0/P0-U02`);
    lines.push(``);
    lines.push(`Generated: ${inventory.generated_at}`);
    lines.push(`Schema: ${inventory.schemaVersion}`);
    lines.push(``);
    lines.push(`## Summary`);
    lines.push(``);
    lines.push(`- **Total hooks**: ${inventory.total_hooks}`);
    lines.push(`- **CCM-planned (declared by envelope, not on disk)**: ${inventory.ccm_planned_count}`);
    lines.push(``);
    lines.push(`## By status`);
    lines.push(``);
    for (const k of ["wired", "orphan", "disabled", "planned"] as const) {
      lines.push(`- **${k}**: ${inventory.by_status[k]}`);
    }
    lines.push(``);
    lines.push(`## By automation-lifecycle stage`);
    lines.push(``);
    for (const s of ALL_STAGES) {
      lines.push(`- **${s}**: ${inventory.by_stage[s]}`);
    }
    lines.push(``);
    lines.push(`## Stage definitions`);
    lines.push(``);
    lines.push(`- \`authoring\` — UserPromptSubmit / SessionStart context injectors`);
    lines.push(`- \`pre_execution\` — PreToolUse safety/dedup/wiring gates`);
    lines.push(`- \`post_execution\` — PostToolUse linters + Stop observers (non-T0)`);
    lines.push(`- \`turn_end_gate\` — Stop blockers at tier T0 (build/test/scrutiny gates)`);
    lines.push(`- \`context_boundary\` — PreCompact handlers`);
    lines.push(`- \`async_background\` — T4 detached / fire-and-forget`);
    lines.push(`- \`unclassified\` — disabled, orphan, or no recognized events`);
    if (inventory.ccm_planned_count > 0) {
      lines.push(``);
      lines.push(`## CCM-planned hooks (declared, not yet built)`);
      lines.push(``);
      const planned = inventory.entries.filter((e) => e.ccmPlanned);
      for (const e of planned) {
        lines.push(`- \`${e.id}\` — declared by ${e.ccmDeclaredBy ?? "(unknown)"}`);
      }
    }
    return lines.join("\n");
  }

  // ─── private ────────────────────────────────────────────────────────────

  /** Scan milestone envelopes for forge_triple.protective_hook references.
   *  Returns both: (a) lookup of hookId → milestoneId for ANY referenced
   *  hook (existing or planned), and (b) the list of hooks that are
   *  declared but absent from `.claude/hooks/`. */
  private _scanMilestonePlannedHooks(
    milestonesDir: string,
    hooksDir: string,
  ): {
    byHookId: Map<string, { milestoneId: string }>;
    plannedOnly: Array<{ hookId: string; milestoneId: string }>;
  } {
    const byHookId = new Map<string, { milestoneId: string }>();
    const plannedOnly: Array<{ hookId: string; milestoneId: string }> = [];

    let files: string[];
    try {
      files = fs.readdirSync(milestonesDir).filter((f) => f.endsWith(".json"));
    } catch (e) {
      // Graceful degradation — milestones dir absent in test fixtures or in
      // fresh checkouts. Per engines.md "throw descriptive errors" rule we
      // emit a console.error so the silent-degrade is observable.
      console.error(
        `[HookLifecycleStageMapperEngine] milestones dir not readable at ${milestonesDir}: ${(e as Error).message}`,
      );
      return { byHookId, plannedOnly };
    }

    for (const f of files) {
      const full = path.join(milestonesDir, f);
      let env: MilestoneEnvelope;
      try {
        const raw = fs.readFileSync(full, "utf8");
        env = JSON.parse(raw) as MilestoneEnvelope;
      } catch (e) {
        // Per-file degrade — one malformed envelope shouldn't kill the scan.
        console.error(
          `[HookLifecycleStageMapperEngine] envelope ${f} unreadable: ${(e as Error).message}`,
        );
        continue;
      }
      const protectiveHook = env.forge_triple?.protective_hook;
      if (typeof protectiveHook !== "string" || protectiveHook.length === 0) continue;
      const milestoneId = env.id ?? env.milestone_id ?? path.basename(f, ".json");
      // Normalize hook id — strip leading dirs / .mjs extension.
      const hookId = path.basename(protectiveHook, ".mjs");
      byHookId.set(hookId, { milestoneId });
      const expectedFile = path.join(hooksDir, `${hookId}.mjs`);
      if (!fs.existsSync(expectedFile)) {
        plannedOnly.push({ hookId, milestoneId });
      }
    }
    return { byHookId, plannedOnly };
  }
}

export const hookLifecycleStageMapperEngine = new HookLifecycleStageMapperEngine();
